package com.wizzadrds.theworldremembers.dialogue;
import com.wizzadrds.theworldremembers.memory.Memory; import com.wizzadrds.theworldremembers.memory.MemoryEventType; import com.wizzadrds.theworldremembers.relationship.Relationship; import java.util.*;
public final class NpcDialogue { private NpcDialogue(){} public static String reply(String name, Relationship relationship, List<Memory> memories){ Optional<Memory> previous=memories.stream().filter(m->m.type()!=MemoryEventType.PLAYER_TALKED).max(Comparator.comparingLong(Memory::gameTime)); if(previous.isPresent()) return switch(previous.get().type()){case PLAYER_GAVE_BREAD->"I remember the bread you gave me.";case PLAYER_GAVE_ITEM->"I remember the "+previous.get().itemId().orElse("item")+" you gave me.";case PLAYER_ATTACKED_NPC->"I haven't forgotten that you hurt me.";case PLAYER_ENTERED_NPC_HOME->"Please respect my home.";case PLAYER_SAVED_NPC->"I remember when you helped me.";default->"I remember something you did.";}; if(relationship.isHostile())return "I don't trust you yet.";if(relationship.isTrusted())return "Good to see you again.";return "Hello. I am "+name+".";}}
